// kit sync: the generated copies in a project and their drift check; see scripts/kit.mjs
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { HEAD, HELPERS, LINE, STAGED, SYNC, at, codeLines, read, readLF, sha, toolsIn, tryGitIn } from "./shared.mjs";

const CHECK_SH = `#!/usr/bin/env sh
# Generated by ai-kit, never edit. Runs ai/kit/pre-commit.sh on the files changed from a base ref, for a gate with no
# plugin: sh ai/kit/check.sh origin/main. It only reads HEAD and the index, so a killed run leaves nothing to restore;
# a project check that writes the index skips itself here (docs/ai-layout.md).
base="$1"
[ -n "$base" ] || { echo "usage: sh ai/kit/check.sh <base-ref>"; exit 2; }
# AI_KIT_RANGE expands unquoted: split words make git diff fail, and a check piping it would read that as no change
case "$base" in *[[:space:]]*) echo "check blocked: a base ref with a space"; exit 2 ;; esac
cd "$(git rev-parse --show-toplevel)" || exit 1
[ -f ai/kit/pre-commit.sh ] || { echo "check blocked: ai/kit/pre-commit.sh is missing"; exit 1; }
# a check written as [ -n "$(tool ...)" ] passes when the tool is missing: ai/kit/requires.txt names what must exist
command -v node >/dev/null 2>&1 || { echo "check blocked: missing tool(s): node (the kit's checks)"; exit 1; }
[ -f ai/kit/requires.txt ] || { echo "check blocked: ai/kit/requires.txt is missing"; exit 1; }
missing=""
while read -r tool || [ -n "$tool" ]; do
  tool="$(printf '%s' "$tool" | tr -d '\\r')"
  case "$tool" in ''|'#'*) continue ;; esac
  command -v "$tool" >/dev/null 2>&1 || missing="$missing $tool"
done <ai/kit/requires.txt
[ -z "$missing" ] || { echo "check blocked: missing tool(s):$missing (ai/kit/requires.txt)"; exit 1; }
# bash as sh carries on past a syntax error in a sourced file, which would reach the exit 0 below
sh -n ai/kit/pre-commit.sh || { echo "check blocked: ai/kit/pre-commit.sh does not parse"; exit 1; }
# a gate on a staged diff would find nothing here and pass without checking anything
if grep -v '^[[:space:]]*#' ai/kit/pre-commit.sh | grep -qE -e '${STAGED}'; then
  echo "check blocked: ai/kit/pre-commit.sh reads the staged diff; use changed and \\$AI_KIT_RANGE (the plugin's template)"
  exit 1
fi
# not exported: a list over the kernel's limit would make every command it runs fail, and a failed gate reads as a pass
AI_KIT_FILES="$(git -c core.quotePath=false diff --name-only --diff-filter=ACMR "$base...HEAD")" || {
  echo "check blocked: no diff from $base (a shallow clone needs the base's history)"
  exit 1
}
# the kit's own checks; the 40 KB rule stays out: a range cannot tell its move-only commit from the edit after it
node ai/kit/checks/check-docs.mjs --range="$base...HEAD" --strict || exit 1
node ai/kit/checks/check-comments.mjs --range="$base...HEAD" --strict || exit 1
${HELPERS}AI_KIT_RANGE="$base...HEAD"
# shellcheck source=/dev/null
. ai/kit/pre-commit.sh
echo "checked $(changed | grep -c .) file(s) from $base"
exit 0
`;

// general.md, the config's files, and each file's "Adds to" list, followed through; plugin docs keep the kit's name
const bodies = (kit, conf) => {
  const out = new Map();
  const visit = (n) => {
    const t = readLF(join(kit, "conventions", n));
    if (t === null || out.has(n)) return;
    out.set(n, t.replace(/`docs\//g, "`ai-kit/docs/"));
    const adds = t.match(/Adds to ([^\n]*(?:\n[^\n]+)*)/)?.[1] ?? "";
    for (const [, f] of adds.matchAll(/`([\w-]+\.md)`/g)) visit(f);
  };
  visit("general.md");
  visit("unattended.md");
  const convs = conf?.conventions;
  for (const c of Array.isArray(convs) ? convs : []) visit(`${c}.md`);
  return out;
};

// generated files outside conventions/: path in the repo -> [source in the plugin, comment style, body]
const REVIEW_NOTE = `A runner's output schema wins over the reply format below. The runner names the diff file.\n\n`;

const reviewBody = (kit) =>
  REVIEW_NOTE +
  readLF(join(kit, "agents", "change-reviewer.md"))
    .replace(/^---\n[\s\S]*?\n---\n\n/, "")
    .replaceAll("${CLAUDE_PLUGIN_ROOT}/conventions/", "ai/kit/conventions/")
    .replaceAll("${CLAUDE_PLUGIN_ROOT}/docs/", "ai-kit/docs/")
    .replace(/Run only read-only commands \([^)]*\)\. /, "");

const extras = (kit) =>
  new Map([
    ["ai/kit/review-prompt.md", ["agents/change-reviewer.md", "md", reviewBody(kit)]],
    ["ai/kit/checks/check-comments.mjs", ["scripts/check-comments.mjs", "js", readLF(join(kit, "scripts", "check-comments.mjs"))]],
    ["ai/kit/checks/check-docs.mjs", ["scripts/check-docs.mjs", "js", readLF(join(kit, "scripts", "check-docs.mjs"))]],
  ]);

const headOf = (version, src, style, body) => {
  const text = `generated by ai-kit ${version} from ${src}, never edit; sha256 ${sha(body)}`;
  return style === "md" ? `<!-- ${text} -->\n\n` : `// ${text}\n\n`;
};

const dirFiles = (dir) =>
  existsSync(dir)
    ? readdirSync(dir, { withFileTypes: true }).filter((e) => e.isFile()).map((e) => e.name)
    : [];

const generated = (dir) => dirFiles(dir).filter((f) => HEAD.test(readLF(join(dir, f))));

const intact = (t) => t.match(HEAD)?.[1] === sha(t.replace(HEAD, ""));

const hasLine = (t) => t?.split("\n").some((l) => l.trim() === LINE) ?? false;

// null when the project has not opted in, else how many files it left; a current copy stays, whatever kit wrote it
function syncSnapshot(root, kit, conf) {
  if (conf?.unattended !== true) return null;
  let left = 0;
  const version = JSON.parse(readLF(join(kit, ".claude-plugin", "plugin.json"))).version;
  const dir = join(root, "ai", "kit", "conventions");
  mkdirSync(dir, { recursive: true });
  const want = bodies(kit, conf);
  for (const [n, body] of want) {
    const p = join(dir, n);
    const t = readLF(p);
    if (t !== null && !HEAD.test(t)) {
      console.log(`! ai/kit/conventions/${n} is not a generated copy: left as it is`);
      left++;
      continue;
    }
    if (t?.match(HEAD)?.[1] === sha(body) && t.replace(HEAD, "") === body) continue;
    writeFileSync(p, headOf(version, `conventions/${n}`, "md", body) + body);
    console.log(`~ ai/kit/conventions/${n}`);
  }
  for (const f of generated(dir))
    if (!want.has(f)) {
      if (!intact(readLF(join(dir, f)))) {
        console.log(`! ai/kit/conventions/${f} no longer applies and was edited by hand: left as it is`);
        left++;
        continue;
      }
      rmSync(join(dir, f));
      console.log(`- ai/kit/conventions/${f}`);
    }
  for (const [rel, [src, style, body]] of extras(kit)) {
    const p = join(root, rel);
    const t = readLF(p);
    if (t !== null && !HEAD.test(t)) {
      console.log(`! ${rel} is not a generated copy: left as it is`);
      left++;
      continue;
    }
    if (t?.match(HEAD)?.[1] === sha(body) && t.replace(HEAD, "") === body) continue;
    mkdirSync(join(p, ".."), { recursive: true });
    writeFileSync(p, headOf(version, src, style, body) + body);
    console.log(`~ ${rel}`);
  }
  const req = join(root, "ai", "kit", "requires.txt");
  if (!existsSync(req)) {
    const tools = toolsIn(codeLines(readLF(join(root, "ai", "kit", "pre-commit.sh")) ?? "").join("\n"));
    writeFileSync(req, `# Commands ai/kit/pre-commit.sh needs, one per line; ai/kit/check.sh stops when one is missing.\n${tools.map((x) => `${x}\n`).join("")}`);
    console.log(`~ ai/kit/requires.txt: ${tools.join(" ") || "no known command"}; a start, add what it does not know`);
  }
  if (readLF(join(root, "ai", "kit", "check.sh")) !== CHECK_SH) {
    writeFileSync(join(root, "ai", "kit", "check.sh"), CHECK_SH);
    console.log("~ ai/kit/check.sh");
  }
  const cp = join(root, "CLAUDE.md");
  const claude = readLF(cp);
  if (!hasLine(claude)) {
    const raw = existsSync(cp) ? readFileSync(cp, "utf8") : "";
    const eol = raw.includes("\r\n") ? "\r\n" : "\n";
    writeFileSync(cp, `${raw}${raw && !raw.endsWith("\n") ? eol : ""}${raw ? eol : ""}${LINE}${eol}`);
    console.log("~ CLAUDE.md");
  }
  return left;
}

// "pre-commit.sh:4 `git diff --cached --name-only`": the first code line that reads the staged diff, by its file line
const stagedAt = (text) => {
  const lines = text.split("\n");
  const i = lines.findIndex((l) => !/^\s*#/.test(l) && new RegExp(STAGED).test(l));
  return i < 0 ? null : `ai/kit/pre-commit.sh:${i + 1} \`${lines[i].trim().slice(0, 80)}\``;
};

function snapshotWarnings(root, kit, conf) {
  if (conf?.unattended !== undefined && typeof conf.unattended !== "boolean")
    return ["ai/kit/config.json unattended must be true or false (fix: write it as true, or remove it)"];
  if (conf?.unattended !== true) {
    const off = readLF(join(root, "ai", "kit", "pre-commit.sh"));
    const hit = off === null ? null : stagedAt(off);
    return hit
      ? [`${hit} reads the staged diff, and a run without the plugin has no index (fix: use changed and $AI_KIT_RANGE, or kit.mjs unattended --dry-run lists the rewrite; ignore it while unattended stays off)`]
      : [];
  }
  const out = [];
  const dir = join(root, "ai", "kit", "conventions");
  const want = bodies(kit, conf);
  for (const [n, body] of want) {
    const t = readLF(join(dir, n));
    const name = `ai/kit/conventions/${n}`;
    if (t === null) out.push(`${name} is missing (${SYNC})`);
    else if (!HEAD.test(t)) out.push(`${name} is not a generated copy (fix: move it out, then run kit.mjs sync)`);
    else if (!intact(t)) out.push(`${name} was edited by hand (${SYNC}, which replaces it)`);
    else if (t.replace(HEAD, "") !== body) out.push(`${name} is stale against the plugin (${SYNC})`);
  }
  for (const f of generated(dir))
    if (!want.has(f)) out.push(`ai/kit/conventions/${f} no longer applies to this project (${SYNC}, or delete it when edited by hand)`);
  for (const [rel, [, , body]] of extras(kit)) {
    const t = readLF(join(root, rel));
    if (t === null) out.push(`${rel} is missing (${SYNC})`);
    else if (!HEAD.test(t)) out.push(`${rel} is not a generated copy (fix: move it out, then run kit.mjs sync)`);
    else if (!intact(t)) out.push(`${rel} was edited by hand (${SYNC}, which replaces it)`);
    else if (t.replace(HEAD, "") !== body) out.push(`${rel} is stale against the plugin (${SYNC})`);
  }
  // an ignored copy works here and is absent from every clone, where check.sh then fails each run
  for (const rel of ["ai/kit/check.sh", "ai/kit/requires.txt", ...extras(kit).keys()])
    if (tryGitIn(root, ["check-ignore", "-q", "--no-index", rel]) !== null)
      out.push(`${rel} is ignored by git, so a clone will not have it (fix: add !${rel} to .gitignore)`);
  if (readLF(join(root, "ai", "kit", "check.sh")) !== CHECK_SH) out.push(`ai/kit/check.sh is missing or changed (${SYNC})`);
  if (readLF(join(root, "ai", "kit", "requires.txt")) === null)
    out.push(`ai/kit/requires.txt is missing, so ai/kit/check.sh refuses to run (${SYNC}, then add what it does not know)`);
  if (!hasLine(readLF(join(root, "CLAUDE.md")))) out.push(`CLAUDE.md does not point to ai/kit/conventions/ (${SYNC})`);
  if (!readLF(join(root, ".githooks", "pre-commit"))?.includes("AI_KIT_RANGE="))
    out.push(".githooks/pre-commit is an older shim: $AI_KIT_RANGE is empty there, so a check on it reads the work tree at commit (fix: kit.mjs init)");
  const pc = readLF(join(root, "ai", "kit", "pre-commit.sh"));
  if (pc === null) return [...out, "ai/kit/pre-commit.sh is missing, so ai/kit/check.sh refuses to run (fix: kit.mjs init)"];
  const lines = codeLines(pc);
  const code = lines.join("\n");
  if (lines.some((l) => new RegExp(STAGED).test(l)))
    out.push(
      `${stagedAt(pc)} reads the staged diff, so ai/kit/check.sh refuses to run (fix: kit.mjs unattended rewrites what it can; else use changed and $AI_KIT_RANGE, as the plugin's templates/ai-kit-project/pre-commit.sh shows)`,
    );
  else if (!code.trim()) out.push("ai/kit/pre-commit.sh has no checks, so ai/kit/check.sh passes whatever changed (fix: add the project's checks)");
  return out;
}

export { snapshotWarnings, syncSnapshot };
